/* ============================================================================
   fuentes.h  -  Tipografías para la pantalla
   ----------------------------------------------------------------------------
   Las letras que trae la librería Adafruit GFX no tienen tildes ni el
   símbolo de grados (°), y sus números grandes se ven "pixelados".
   Por eso generamos fuentes propias a partir de la tipografía libre
   "Inter" (licencia SIL Open Font License) con la herramienta
   "fontconvert" que viene con Adafruit GFX.

   Cada fuente es una tabla de datos (no es código para leer):
     - HoraInter46pt7b   : solo números, "-", "." y ":" en tamaño grande (hora)
     - TituloInter16pt8b : texto en negrita con tildes (día, títulos)
     - TextoInter13pt8b  : texto normal con tildes (fecha, mensajes)
     - TempInter22pt8b   : texto mediano con tildes y "°" (temperatura)

   Las fuentes "8b" incluyen los caracteres Latin-1 (á, é, í, ó, ú, ñ, °).
   En el programa principal, la función aLatin1() convierte los textos
   escritos en el código (UTF-8) a ese formato antes de dibujarlos.
   ============================================================================ */
